// The NAP a listing publishes: the operator row, field by field, over the vendor row. A blank field
// counts as absent: Payload saves a cleared text box as ''.
export function publishedNap(records: readonly NapRecord[]): PublishedNap {
  const rows = (['operator', 'vendor'] as const).flatMap(
    (source) => records.find((record) => record.source === source) ?? [],
  )
  const from = (field: NapField) => rows.find((row) => row[field] != null && row[field] !== '')
  return {
    name: from('name')?.name ?? null,
    address: from('address')?.address ?? null,
    phone: from('phone')?.phone ?? null,
    hours: from('hours')?.hours ?? null,
    sources: Object.fromEntries(
      napFields.map((field) => [field, from(field)?.source ?? null]),
    ) as PublishedNap['sources'],
  }
